from __future__ import annotations

from gitseed.grade.smoke import CLEAN_DIGEST, MALICIOUS_DIGEST, run_smoke
from gitseed.grade.types import GradeResult


class ModelSwitchingClient:
    """Returns stable grades but switches the serving model on the last sample."""

    def __init__(self) -> None:
        self._evaluations = 0

    def evaluate(self, digest: str) -> GradeResult:
        self._evaluations += 1
        model = "stable-grader:1" if self._evaluations < 5 else "replacement-grader:2"
        return GradeResult(
            idea=7,
            skill=8,
            description="A harmless structured logger.",
            model=model,
            temperature=0.0,
            prompt_version="smoke-v1",
        )

    def flags_malicious(self, digest: str) -> bool:
        if digest == CLEAN_DIGEST:
            return False
        if digest == MALICIOUS_DIGEST:
            return True
        raise AssertionError("unexpected smoke digest")


def test_smoke_rejects_a_backend_that_changes_models_between_samples() -> None:
    result = run_smoke(ModelSwitchingClient())

    assert result.passed is False
    assert any(
        "model" in failure.lower()
        and "stable-grader:1" in failure
        and "replacement-grader:2" in failure
        for failure in result.failures
    )
